const GM01_NEED = 2
game gm01_phase
game gm01_run
game gm01_queue: list
game gm01_alive: list
game gm01_wins

func gm01_drop(gm01_who: text) {
    gm01_queue = remove_list_value(gm01_queue, gm01_who, remove_mode: all)
    gm01_alive = remove_list_value(gm01_alive, gm01_who, remove_mode: all)
}

func gm01_try() {
    if gm01_phase == "lobby" and len(gm01_queue) >= GM01_NEED {
        gm01_phase = "count"
        gm01_run += 1
        start gm01_match(target_mode: no_target)
    }
}

process gm01_helper(gm01_id: number) {
    wait(10)
    while gm01_run == gm01_id and gm01_phase == "run" {
        @all send_message("gm01 помощник ${gm01_id}")
        wait(10)
    }
}

process gm01_match() {
    gm01_left = 2
    while gm01_left > 0 and len(gm01_queue) >= GM01_NEED {
        @all send_message("gm01 отсчёт ${gm01_left}")
        wait(10)
        gm01_left -= 1
    }
    if gm01_left > 0 or len(gm01_queue) < GM01_NEED {
        gm01_phase = "lobby"
        @all send_message("gm01 отмена")
        return
    }
    gm01_phase = "run"
    gm01_alive = randomize_list_order(gm01_queue)
    gm01_queue = []
    @all send_message("gm01 бой ${len(gm01_alive)}")
    start gm01_helper(gm01_run, target_mode: no_target)
    gm01_left = 200
    while gm01_left > 0 and len(gm01_alive) > 1 {
        wait(5)
        gm01_left -= 1
    }
    gm01_phase = "end"
    gm01_wins += 1
    @all send_message("gm01 победил ${get_list_value(gm01_alive, 0, "никто")} раз ${gm01_wins}")
    gm01_alive = []
    gm01_phase = "lobby"
    gm01_try()
}

when world_start {
    gm01_phase, gm01_run, gm01_wins = "lobby", 0, 0
    gm01_queue, gm01_alive = [], []
}

when player_chat {
    if chat_message_equals("@gm01") {
        cancel_event()
        gm01_queue = [value.name, "gm01_bot"]
        gm01_try()
    }
    if chat_message_equals("@gm01k") {
        cancel_event()
        gm01_drop("gm01_bot")
        gm01_drop("gm01_bot")
        gm01_drop("gm01_bot")
    }
    if chat_message_equals("@gm01q") {
        cancel_event()
        gm01_drop("gm01_bot")
    }
}

