func gm10_buy(gm10_key: text, gm10_base: number, gm10_top: number) {
    gm10_lvl = get_map_value_single(`gm10_ур %player%`, gm10_key, 0)
    gm10_cost = floor(gm10_base * pow(1.5, gm10_lvl))
    if gm10_lvl >= gm10_top {
        send_message("gm10 максимум")
        return
    }
    if `gm10_деньги %player%` < gm10_cost {
        send_message("gm10 нужно ${gm10_cost}")
        return
    }
    `gm10_деньги %player%` -= gm10_cost
    `gm10_ур %player%`[gm10_key] = gm10_lvl + 1
    send_message("gm10 уровень ${gm10_lvl + 1} цена ${gm10_cost}")
}

when player_chat {
    gm10_args = split_text(value.event_chat_message, " ")
    if gm10_args[0] != "@gm10p" {
        end_thread()
    }
    cancel_event()
    gm10_to = get_list_value(gm10_args, 1, "")
    gm10_sum = get_list_value(gm10_args, 2, "")
    if not text_matches("^[1-9][0-9]{0,8}$", gm10_sum, regular_expressions: true) {
        send_message("gm10 плохая сумма")
        end_thread()
    }
    gm10_sum = add(gm10_sum)
    if gm10_to == value.name or not var.exists(`gm10_деньги %var_local(gm10_to)`) {
        send_message("gm10 нет счёта")
        end_thread()
    }
    if `gm10_деньги %player%` < gm10_sum {
        send_message("gm10 не хватает")
        end_thread()
    }
    `gm10_деньги %player%` -= gm10_sum
    `gm10_деньги %var_local(gm10_to)` += gm10_sum
    send_message("gm10 переведено ${gm10_sum}")
}

