func gm11_roll(gm11_ch: list) {
    gm11_total = 0
    for gm11_w in gm11_ch {
        gm11_total += gm11_w
    }
    gm11_hit = random_number(0, gm11_total, integer: false)
    gm11_acc = 0
    for gm11_at, gm11_w2 in gm11_ch {
        gm11_acc += gm11_w2
        if gm11_hit <= gm11_acc {
            return gm11_at
        }
    }
    return 0
}

