func gm12_claim() {
    if has_player(value.uuid) and var.exists(`gm12_приз %player%`) {
        give_items(`gm12_приз %player%`)
        var.remove(`gm12_приз %player%`)
    }
}

func gm12_open() {
    if var.exists(`gm12_приз %player%`) {
        send_message("gm12 занято")
        return
    }
    if `gm12_ключи %player%` < 1 {
        send_message("gm12 нет ключа")
        return
    }
    `gm12_ключи %player%` -= 1
    `gm12_приз %player%` = get_list_value(GM12_LOOT, gm12_roll([0, 1]))
    start gm12_spin()
}

process gm12_spin() {
    gm12_tape = []
    repeat 30 {
        gm12_tape = append_value(get_list_value(GM12_LOOT, gm12_roll([1, 0])))
    }
    gm12_tape[26] = `gm12_приз %player%`
    show_inventory_menu(name: "gm12 Кейс", custom_id: "gm12spin")
    set_inventory_menu_item(item(hopper, name: "Выигрыш"), 4)
    gm12_frames = 0
    for gm12_pos in 0..22 {
        if value.open_inventory_custom_id != "gm12spin" {
            break
        }
        for gm12_cell in 0..8 {
            set_inventory_menu_item(get_list_value(gm12_tape, gm12_pos + gm12_cell), 9 + gm12_cell)
        }
        gm12_frames += 1
        wait(1 + floor(gm12_pos / 6))
    }
    if gm12_frames == 23 {
        gm12_mid = get_list_value(value.custom_inventory_items, 13)
        send_message("gm12 центр ${get_item_type(gm12_mid, value: id)}")
    }
    send_message("gm12 кадров ${gm12_frames}")
    gm12_claim()
}

