func gm13_add(gm13_n: number) {
    `gm13_xp %player%` += gm13_n
    while `gm13_xp %player%` >= 100 * (`gm13_lvl %player%` + 1) {
        `gm13_xp %player%` -= 100 * (`gm13_lvl %player%` + 1)
        `gm13_lvl %player%` += 1
    }
    set_experience(`gm13_lvl %player%`, mode: level)
    wait(2)
    send_message("gm13 ур ${`gm13_lvl %player%`} xp ${`gm13_xp %player%`} шкала ${value.experience_level}")
